#include <stddef.h>
#include <stdio.h>

int main(void)
{
    const int values[] = {10, 20, 30};
    const size_t count = sizeof values / sizeof values[0];
    const size_t index = 2U;

    if (index >= count) {
        fputs("index out of range\n", stderr);
        return 1;
    }
    printf("value=%d\n", values[index]);
    return 0;
}

