#include <limits.h>
#include <stdbool.h>
#include <stdio.h>

static bool add_checked(int left, int right, int *result)
{
    if (result == NULL) {
        return false;
    }
    if ((right > 0 && left > INT_MAX - right) ||
        (right < 0 && left < INT_MIN - right)) {
        return false;
    }
    *result = left + right;
    return true;
}

int main(void)
{
    int answer = 0;
    if (!add_checked(20, 22, &answer)) {
        return 1;
    }
    printf("sum=%d\n", answer);
    return 0;
}
